const errorData = $input.first().json;

const workflowName = errorData.workflow?.name || 'Unknown Workflow';
const executionId = errorData.execution?.id || 'N/A';
const errorMessage = errorData.execution?.error?.message || 'Unbekannter Fehler';
const errorDescription = errorData.execution?.error?.description || '';
const executionUrl = errorData.execution?.url || '';
const workflowId = errorData.workflow?.id || 'unknown';

const bodyHtml = `<h2>Workflow Fehler aufgetreten</h2>
<table style="border-collapse:collapse;width:100%;font-family:Arial,sans-serif;">
<tr style="background:#f44336;color:white;"><td style="padding:10px;" colspan="2"><strong>Fehlerbericht</strong></td></tr>
<tr><td style="padding:8px;border:1px solid #ddd;width:150px;"><strong>Workflow</strong></td><td style="padding:8px;border:1px solid #ddd;">${workflowName}</td></tr>
<tr><td style="padding:8px;border:1px solid #ddd;"><strong>Execution ID</strong></td><td style="padding:8px;border:1px solid #ddd;">${executionId}</td></tr>
<tr><td style="padding:8px;border:1px solid #ddd;"><strong>Fehlermeldung</strong></td><td style="padding:8px;border:1px solid #ddd;color:#d32f2f;">${errorMessage}</td></tr>
<tr><td style="padding:8px;border:1px solid #ddd;"><strong>Beschreibung</strong></td><td style="padding:8px;border:1px solid #ddd;">${errorDescription || 'Keine Beschreibung'}</td></tr>
<tr><td style="padding:8px;border:1px solid #ddd;"><strong>Execution Link</strong></td><td style="padding:8px;border:1px solid #ddd;"><a href="${executionUrl}">${executionUrl}</a></td></tr>
</table>`;

return [{
  json: {
    alert_type: 'error',
    severity_hint: 'warning',
    source_workflow_id: workflowId,
    source_workflow_name: workflowName,
    subject: `N8N Fehler: ${workflowName}`,
    body_html: bodyHtml,
    metadata: {
      execution_id: executionId,
      execution_url: executionUrl,
      error_message: errorMessage,
      error_description: errorDescription
    }
  }
}];
